    39	public static class ApiHelpers
    40	{
    41	    /// <summary>
    42	    /// Sends a request as <paramref name="user"/> (a bearer token signed for that seeded user and
    43	    /// their roles) or with a raw <paramref name="token"/>; neither means no Authorization header.
    44	    /// </summary>
    45	    public static async Task<HttpResponseMessage> SendAsync(
    46	        this HttpClient client, HttpMethod method, string url, object? body = null, Guid? user = null, string? token = null)
    47	    {
    48	        using var request = new HttpRequestMessage(method, url);
    49	        if (body is string raw)
    50	        {
    51	            // Raw JSON text, for malformed or hand-written bodies.
    52	            request.Content = new StringContent(raw, System.Text.Encoding.UTF8, "application/json");
    53	        }
    54	        else if (body is not null)
    55	        {
    56	            request.Content = JsonContent.Create(body);
    57	        }
    58	        token ??= user is null ? null : TestTokens.For(user.Value);
    59	        if (token is not null)
    60	        {
    61	            request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token);
    62	        }
    63	        return await client.SendAsync(request);
    64	    }
    65	
    66	    /// <summary>GET as a seeded user.</summary>
    67	    public static Task<HttpResponseMessage> GetAsync(this HttpClient client, string url, Guid user) =>
    68	        client.SendAsync(HttpMethod.Get, url, user: user);
    69	
    70	    public static async Task<JsonElement> JsonAsync(this HttpResponseMessage response)
    71	    {
    72	        var text = await response.Content.ReadAsStringAsync();
    73	        Assert.False(string.IsNullOrWhiteSpace(text), $"Expected a JSON body, got an empty one ({(int)response.StatusCode}).");
    74	        using var doc = JsonDocument.Parse(text);
    75	        return doc.RootElement.Clone();
    76	    }
    77	
    78	    public static async Task AssertStatusAsync(this HttpResponseMessage response, System.Net.HttpStatusCode expected)
    79	    {
    80	        if (response.StatusCode != expected)
    81	        {
    82	            var body = await response.Content.ReadAsStringAsync();
    83	            Assert.Fail($"Expected {(int)expected} {expected}, got {(int)response.StatusCode} {response.StatusCode}: {body}");
    84	        }
    85	    }
