    21	/// <summary>A clock the tests can move forward (for due dates and overdue devices).</summary>
    22	public sealed class TestClock : TimeProvider
    23	{
    24	    private DateTimeOffset _now = new(2026, 11, 14, 9, 0, 0, TimeSpan.Zero);
    25	
    26	    public override DateTimeOffset GetUtcNow() => _now;
    27	
    28	    public void Advance(TimeSpan by) => _now = _now.Add(by);
    29	}
    30	
    31	/// <summary>Keeps every log line the API writes so tests can check what reached the log.</summary>
    32	public sealed class CapturedLogs : ILoggerProvider
    33	{
    34	    private readonly ConcurrentQueue<string> _lines = new();
    35	
    36	    public IReadOnlyCollection<string> Lines => _lines.ToArray();
    37	
    38	    public ILogger CreateLogger(string categoryName) => new Logger(this, categoryName);
    39	
    40	    public void Dispose()
    41	    {
    42	    }
    43	
    44	    private sealed class Logger(CapturedLogs owner, string category) : ILogger
    45	    {
    46	        public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;
    47	
    48	        public bool IsEnabled(LogLevel logLevel) => true;
    49	
    50	        public void Log<TState>(LogLevel logLevel, EventId eventId, TState state, Exception? exception, Func<TState, Exception?, string> formatter) =>
    51	            owner._lines.Enqueue($"{logLevel} {category}: {formatter(state, exception)} {exception}");
    52	    }
    53	}
    54	
    55	/// <summary>
    56	/// Runs the API in memory against its own PostgreSQL database, created (and migrated and
    57	/// seeded) at startup and dropped when the test class finishes.
    58	/// </summary>
    59	public class HubApiFactory : WebApplicationFactory<Program>, IAsyncLifetime
    60	{
    61	    /// <summary>A random AES-256 key for this test run only.</summary>
    62	    public static readonly string FieldKey = Convert.ToBase64String(RandomNumberGenerator.GetBytes(32));
    63	
    64	    private readonly string _databaseName = $"rh_test_{Guid.NewGuid():N}";
    65	
    66	    public TestClock Clock { get; } = new();
    67	
    68	    public CapturedLogs Logs { get; } = new();
    69	
    70	    protected virtual string ConnectionString => TestDb.ForDatabase(_databaseName);
    71	
    72	    protected override void ConfigureWebHost(IWebHostBuilder builder)
    73	    {
    74	        builder.UseEnvironment("Testing");
    75	        builder.UseSetting("ConnectionStrings:HubDb", ConnectionString);
    76	        builder.UseSetting("JWT_JWKS_PATH", TestTokens.JwksPath);
    77	        builder.UseSetting("JWT_ISSUER", TestTokens.Issuer);
    78	        builder.UseSetting("JWT_AUDIENCE", TestTokens.Audience);
    79	        builder.UseSetting("FIELD_ENCRYPTION_KEY", FieldKey);
    80	        builder.ConfigureLogging(logging => logging.AddProvider(Logs));
    81	        builder.ConfigureServices(services =>
    82	        {
    83	            services.RemoveAll<TimeProvider>();
    84	            services.AddSingleton<TimeProvider>(Clock);
    85	        });
    86	    }
