    96	    public async Task<T> WithDbAsync<T>(Func<HubDbContext, Task<T>> work)
    97	    {
    98	        using var scope = Services.CreateScope();
    99	        return await work(scope.ServiceProvider.GetRequiredService<HubDbContext>());
   100	    }
