   110	    async Task IAsyncLifetime.DisposeAsync()
   111	    {
   112	        await base.DisposeAsync();
   113	        if (TestDb.BaseConnectionString is null)
   114	        {
   115	            return;
   116	        }
   117	
   118	        NpgsqlConnection.ClearAllPools();
   119	        await using var connection = new NpgsqlConnection(TestDb.BaseConnectionString);
   120	        await connection.OpenAsync();
   121	        await using var command = connection.CreateCommand();
   122	        // The name is generated above from a GUID, never from input.
   123	        command.CommandText = $"DROP DATABASE IF EXISTS \"{_databaseName}\" WITH (FORCE)";
   124	        await command.ExecuteNonQueryAsync();
   125	    }
   126	}
